er.amount.toFixed(2) }}</td><td><span class="payment-status" :class="paymentClass(order.paymentStatus)">{{ order.paymentStatus }}</span></td><td><span class="order-status" :class="statusClass(order.status)">{{ order.status }}</span></td><td class="order-actions"><button class="table-action" @click="openDetail(order)">查看详情</button><button v-if="order.status !== '已取消' && order.status !== '已完成'" class="table-action danger" @click="cancelOrder(order)">取消</button><button class="table-action" @click="notify(`已发送 ${order.id} 打印任务`)">打印</button></td></tr><tr v-if="!filteredOrders.length"><td colspan="8" class="order-empty">没有找到符合条件的订单</td></tr></tbody></table></div><div class="pagination"><button disabled>‹</button><span class="active">1</span><button>2</button><button>3</button><span>…</span><button>›</button></div></section>
