const filteredOrders = computed(() => orders.value.filter(order => { const query = keyword.value.toLowerCase(); return (!query || order.id.toLowerCase().includes(query) || order.phone.includes(query)) && (statusFilter.value === '全部状态' || order.status === statusFilter.value) && (timeFilter.value === '全部时间' || order.dateGroup === timeFilter.value) && (sourceFilter.value === '全部来源' || order.source === sourceFilter.value) && (paymentFilter.value === '全部支付状态' || order.paymentStatus === paymentFilter.value) && (!metricFilter.value || (metricFilter.value === 'completed' && order.status === '已完成') || (metricFilter.value === 'pending' && ['待备货', '配送中'].includes(order.status)) || (metricFilter.value === 'cancelled' && order.status === '已取消')) }))
